//! Old ray diagrams, frozen: 160 saved figures and their share links made before batch 5 (at 303d812, the figure's
//! fifteen old controls), each with the hash of the SVG it drew then. A saved figure stores every param; a share link
//! lists only those that differ from the opening state. Both must still draw byte for byte what they drew.
//!
//! The fixture was written by the old code with `VERSHION_RAY_FREEZE=1 cargo test --profile figtest --lib ray_diagram_frozen`
//! and must never be regenerated by the new code.
use crate::figures::spec::{params_from_spec, value_to_json};
use crate::figures::{registry, start_params, FigureDef, Params, Value};

fn def() -> FigureDef { registry().into_iter().find(|d| d.id == "ray-diagram").unwrap() }

fn fnv64(s: &str) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for b in s.as_bytes() {
        h ^= *b as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}

fn fixture() -> std::path::PathBuf { std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/ray_diagram_frozen.txt") }

/// The old controls' values, sampled: every kind, the ends of every range and the common textbook cases.
fn old_specs() -> Vec<Vec<(&'static str, Value)>> {
    let kinds = ["Converging lens", "Diverging lens", "Concave mirror", "Convex mirror"];
    let mut seed: u64 = 0x5eed_0f0a_1d00;
    let mut next = |n: u64| { seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407); (seed >> 33) % n };
    let mut out: Vec<Vec<(&'static str, Value)>> = vec![vec![]];
    // the textbook cases for each kind at f = 10
    for k in kinds {
        for d in [2.0, 6.0, 10.0, 15.0, 20.0, 25.0, 30.0, 31.0] {
            out.push(vec![("kind", Value::S(k.into())), ("dist", Value::F(d))]);
        }
    }
    let labels = [("F", "F\u{2032}", "2F", "2F\u{2032}", "O", "I"), ("f", "f'", "C", "", "A", "B"), ("", "", "", "", "", ""), ("Focus", "F\u{2032}", "2F", "2F\u{2032}", "Object", "Image")];
    while out.len() < 160 {
        let kind = kinds[next(4) as usize];
        let f = 2.0 + 0.5 * next(37) as f64;
        let dist = 2.0 + 0.5 * next(59) as f64;
        let height = 0.5 + 0.5 * next(14) as f64;
        let l = labels[next(4) as usize];
        out.push(vec![
            ("kind", Value::S(kind.into())), ("f", Value::F(f)), ("dist", Value::F(dist)), ("height", Value::F(height)),
            ("rays", Value::I(1 + next(3) as i64)), ("image", Value::B(next(4) != 0)), ("show_labels", Value::B(next(5) != 0)),
            ("lab_f", Value::S(l.0.into())), ("lab_f2", Value::S(l.1.into())), ("lab_2f", Value::S(l.2.into())), ("lab_2f2", Value::S(l.3.into())),
            ("lab_o", Value::S(l.4.into())), ("lab_i", Value::S(l.5.into())),
            ("title", Value::S(if next(3) == 0 { "Lenses".into() } else { String::new() })),
            ("show_answers", Value::B(next(4) != 0)), ("label_size", Value::S(["Large", "Medium", "Small"][next(3) as usize].into())),
        ]);
    }
    out
}

/// The params the old code built from a spec: its defaults overlaid with the spec.
fn old_params(d: &FigureDef, list: &[(&'static str, Value)]) -> Params {
    let mut p = Params::defaults(&(d.params)());
    for (k, v) in list { p.0.insert(k.to_string(), v.clone()); }
    p.normalize(&(d.params)(), false);
    p
}

/// Only the keys the old figure had (a saved figure from before stores exactly these).
const OLD_KEYS: [&str; 16] = ["kind", "f", "dist", "height", "rays", "image", "show_labels", "lab_f", "lab_f2", "lab_2f", "lab_2f2", "lab_o", "lab_i", "title", "show_answers", "label_size"];

#[test]
fn ray_diagram_frozen() {
    let d = def();
    if crate::env_var("VERSHION_RAY_FREEZE").is_ok_and(|v| v == "1") {
        let start = start_params(&d);
        let mut text = String::new();
        for list in old_specs() {
            let p = old_params(&d, &list);
            let spec: serde_json::Map<String, serde_json::Value> = OLD_KEYS.iter().map(|k| (k.to_string(), value_to_json(p.0.get(*k).unwrap()))).collect();
            let link: serde_json::Map<String, serde_json::Value> = OLD_KEYS.iter().filter(|k| start.0.get(**k) != p.0.get(**k)).map(|k| (k.to_string(), value_to_json(p.0.get(*k).unwrap()))).collect();
            text.push_str(&format!("{:016x}\t{}\t{}\n", fnv64(&d.svg(&p)), serde_json::Value::Object(spec), serde_json::Value::Object(link)));
        }
        std::fs::write(fixture(), text).unwrap();
        return;
    }
    let text = std::fs::read_to_string(fixture()).unwrap();
    let (mut n, mut changed) = (0, 0);
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        let mut it = line.split('\t');
        let (hash, spec, link) = (it.next().unwrap(), it.next().unwrap(), it.next().unwrap());
        let spec: serde_json::Map<String, serde_json::Value> = serde_json::from_str(spec).unwrap();
        let link: serde_json::Map<String, serde_json::Value> = serde_json::from_str(link).unwrap();
        // a saved figure
        let saved = params_from_spec(&d, &crate::model::FigureSpec { id: d.id.into(), params: spec.clone().into_iter().collect() });
        let shared: Vec<Params> = [crate::figures::share::VERSION, 1].iter().map(|v| crate::figures::share::link_params(&d, link.clone(), *v)).collect();
        if intended(&spec) {
            // the intended changes (see `intended`): the image at C drawn, the infinite ray at F left out
            for p in std::iter::once(&saved).chain(&shared) {
                let svg = d.svg(p);
                assert_ne!(format!("{:016x}", fnv64(&svg)), hash, "{spec:?}: drawn as before");
                assert!(!svg.contains("inf") && !svg.contains("NaN"), "{spec:?}: a coordinate is not finite");
                if (spec["dist"].as_f64().unwrap() - spec["f"].as_f64().unwrap()).abs() > 1e-9 {
                    assert!(svg.contains(r#"stroke-width="3"/><polygon points=""#), "{spec:?}: no image drawn");
                }
            }
            changed += 1;
        } else {
            assert_eq!(format!("{:016x}", fnv64(&d.svg(&saved))), hash, "saved figure {spec:?} draws differently");
            // its share link, made at the current link version and at the first
            for p in &shared {
                assert_eq!(format!("{:016x}", fnv64(&d.svg(p))), hash, "share link {link:?} draws differently");
            }
        }
        n += 1;
    }
    assert_eq!(n, 160);
    assert!(changed <= 8, "{changed} old figures changed on purpose");
    eprintln!("ray diagram frozen: {n} old figures, {changed} changed on purpose");
}

/// The old figures changed on purpose: a concave mirror with its object on C (twice the focal length) whose image the
/// key copy would show, and a converging lens or concave mirror with its object on F drawing its third ray (the old
/// figure wrote it with infinite coordinates, a stray line along the top of the drawing; it is left out now).
fn intended(spec: &serde_json::Map<String, serde_json::Value>) -> bool {
    let num = |k: &str| spec[k].as_f64().unwrap();
    let conv = spec["kind"] == "Concave mirror" || spec["kind"] == "Converging lens";
    let at_c = spec["kind"] == "Concave mirror" && (num("dist") - 2.0 * num("f")).abs() < 1e-9 && spec["image"] == true && spec["show_answers"] == true;
    let at_f = conv && (num("dist") - num("f")).abs() < 1e-9 && spec["rays"] == 3;
    at_c || at_f
}
